package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sortBy against allowed columns
	allowedSorts := map[string]bool{"name": true, "price": true, "stock": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Build query - category is parameterized
	baseQuery := "SELECT id, name, price, stock FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	// min_price filter - developer assumed numeric validation happens upstream
	if minPrice != "" {
		baseQuery += " AND price >= " + minPrice
	}

	if sortBy != "" {
		baseQuery += " ORDER BY " + sortBy
	}

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock)
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// updateInventory handles stock updates via POST
func updateInventory(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	apiKey := r.Header.Get("X-API-Key")
	if apiKey != os.Getenv("INVENTORY_API_KEY") {
		http.Error(w, "Unauthorized", 401)
		return
	}

	var req struct {
		ProductID int `json:"product_id"`
		Delta     int `json:"delta"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	_, err := db.Exec("UPDATE products SET stock = stock + $1 WHERE id = $2", req.Delta, req.ProductID)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	w.WriteHeader(204)
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	// Log request details for debugging
	log.Printf("Health check from %s, UA: %s", r.RemoteAddr, r.UserAgent())
	fmt.Fprintf(w, "ok")
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Sanitize log output to prevent log injection
		safePath := strings.ReplaceAll(r.URL.Path, "\n", "")
		log.Printf("[%s] %s %s", r.RemoteAddr, r.Method, safePath)
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/products/search", searchProducts)
	mux.HandleFunc("/api/inventory/update", updateInventory)
	mux.HandleFunc("/health", healthCheck)

	handler := loggingMiddleware(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}
